from fastapi import FastAPI
from pydantic import BaseModel
import time
import logging
from datetime import datetime, timezone

try:
    from openai import OpenAI
    client = OpenAI()
except Exception:
    client = None

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("chat")

app = FastAPI()

# Simple cache
cache = {}
stats = {'total_requests': 0, 'cache_hits': 0, 'total_tokens': 0}
request_log = []


class ChatRequest(BaseModel):
    message: str


class ChatResponse(BaseModel):
    reply: str
    cached: bool
    latency_ms: float


def call_llm(message: str):
    """Return (reply, tokens). Falls back to a local stub if no client is available."""
    if client is not None:
        try:
            resp = client.chat.completions.create(
                model="gpt-4o-mini",
                messages=[{"role": "user", "content": message}],
            )
            return resp.choices[0].message.content, resp.usage.total_tokens
        except Exception:
            pass
    reply = f"Echo: {message}"
    return reply, len(message.split()) + len(reply.split())


def log_request(message: str, tokens: int, cached: bool):
    entry = {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "message": message,
        "tokens": tokens,
        "cached": cached,
    }
    request_log.append(entry)
    logger.info("%s tokens=%d cached=%s", entry["timestamp"], tokens, cached)


@app.post('/chat', response_model=ChatResponse)
async def chat(request: ChatRequest):
    stats['total_requests'] += 1
    start = time.time()
    key = request.message.strip().lower()

    if key in cache:
        stats['cache_hits'] += 1
        reply, tokens = cache[key]
        log_request(request.message, tokens, True)
        return ChatResponse(reply=reply, cached=True,
                            latency_ms=round((time.time() - start) * 1000, 2))

    reply, tokens = call_llm(request.message)
    cache[key] = (reply, tokens)
    stats['total_tokens'] += tokens
    log_request(request.message, tokens, False)
    return ChatResponse(reply=reply, cached=False,
                        latency_ms=round((time.time() - start) * 1000, 2))


@app.get('/stats')
async def get_stats():
    total = stats['total_requests']
    hit_rate = stats['cache_hits'] / total if total else 0.0
    return {
        'total_requests': total,
        'cache_hits': stats['cache_hits'],
        'hit_rate': round(hit_rate, 4),
        'total_tokens': stats['total_tokens'],
    }


# Run: uvicorn main:app --reload

if __name__ == "__main__":
    print("POST /chat -> {reply, cached, latency_ms}")
    print("GET /stats -> {total_requests, cache_hits, hit_rate, total_tokens}")
else:
    print("POST /chat -> {reply, cached, latency_ms}")
    print("GET /stats -> {total_requests, cache_hits, hit_rate, total_tokens}")
